#include <item/EffectRuntime.hpp>
#include <item/RecoveryRuntime.hpp>
void EnergyCrystalCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,const std::string& password,const std::string& path,const std::vector<BulkSource>& sources){
 using namespace auriga::item;Check(sources.size()==1 && IsEnergyCrystal(*catalog,sources[0].grant.key),"actual original energy crystal source present");
 CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"owned energy SQL connects");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-energy-crystal-worker").has_value(),"actual energy item worker starts");
 const ItemOwner owner{ItemOwnerKind::Character,22001};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"energy owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0,packets=0;bool replay=false;constexpr std::uint64_t now=1794787200000ULL;
 const auto op=[&](){return std::array<std::uint8_t,16>{0x55,static_cast<std::uint8_t>(++serial),static_cast<std::uint8_t>(serial>>8)};};
 const auto apply=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> result;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){result=std::move(out);}),"energy native commit queued");for(unsigned i=0;!result && i<1000;++i){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(result && result->write && result->state,"energy native commit confirmed and reloaded");replay=result->write->replay;if(!replay)runtime::SpendInstanceIds(std::ranges::count_if(commit.items,[](const auto& ch){return !ch.before;}));state=std::move(*result->state);};
 const auto relog=[&](){const auto saved=state;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(state.items==saved.items && state.recovery==saved.recovery,"actual SQL relog retains birth strength and exact timed state");};
 const auto key=sources[0].grant.key;const auto ids=runtime::PeekInstanceIds(256);auto grant=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,{key,0,2},ids);Check(grant.has_value(),"actual original energy crystal receives native birth roll");const auto source=grant->items[0].after;apply(*grant);Check(state.items[0].energy==source.energy,"SQL stores exact native birth roll");
 ItemEffectFacts actor;actor.actor.pools={1000000,1000000,1000000,1000000};actor.actor.level=255;actor.actor.context=RecoveryContext::World;actor.alive=actor.allowed=true;
 const auto file=[&](const std::string& phase,const char* kind,const auto& bytes){std::ofstream out(path+"."+phase+"."+kind+".hex");for(auto b:bytes){const auto x=static_cast<unsigned char>(b);out<<"0123456789abcdef"[x>>4]<<"0123456789abcdef"[x&15];}out<<'\n';Check(out.good(),"actual energy frame exported");};
 const auto output=[&](const std::string& phase,unsigned status,unsigned error=255){
  file(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());
  file(phase,"effects",EncodeItemEffectsRuntime(*catalog,{static_cast<std::uint8_t>(status),static_cast<std::uint8_t>(error),5500,5501,&source,&state.recovery,state.items,now}).value());
  const auto current=std::ranges::find(state.items,source.id,&PersistentItem::id);std::ofstream facts(path+"."+phase+".json");facts<<"{\"source\":"<<source.id.Value()<<",\"percent\":"<<unsigned(source.energy->percent)<<",\"count\":"<<(current==state.items.end() ? 0 : current->count)<<",\"remaining\":"<<(state.recovery.effects.empty() ? 0 : state.recovery.effects[0].remainingMs)<<"}\n";++packets;
 };
 auto underlevel=actor;underlevel.actor.level=34;Check(!MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,source.id,underlevel,0,now,1),"real original level35 gate does not consume");
 const auto first=MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,source.id,actor,0,now,1);Check(first.has_value(),"actual energy use planned");output("ready",1);apply(*first);Check(state.items[0].count==1 && state.recovery.effects[0].energyPercent==source.energy->percent,"energy cost and exact effect strength saved together");output("applied",3);
 const auto saved=state;apply(*first);Check(replay && state.items==saved.items && state.recovery==saved.recovery,"use receipt cannot consume twice or refresh duration");output("replayed",3);relog();output("relogged",3);
 Check(!MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,source.id,actor,0,now,2),"second active energy crystal refused");output("denied",5,14);
 const auto timer=[&](std::uint64_t elapsed,bool dead){auto next=AdvanceRecoverySchedule(*catalog,state.recovery,elapsed).value();auto facts=actor;facts.alive=!dead;NormalizeTimedItems(*catalog,next,now+999999999,&facts);++next.revision;ItemCommit commit;commit.operationId=op();commit.catalogRevision=catalog->Revision();commit.catalogHash=catalog->ContentHash();commit.kind=ItemOperationKind::Service;commit.owners={state.fence};commit.outcomeCode=0x2003;commit.result={'R','T','M',1};commit.recovery=ItemRecoveryChange{owner,state.recovery,next,elapsed};return commit;};
 const auto elapsed=timer(12345,false);apply(elapsed);Check(state.recovery.effects[0].remainingMs==1787655,"actual SQL online elapsed charged precisely");output("elapsed",3);const auto timed=state;apply(elapsed);Check(replay && state.recovery==timed.recovery,"timer replay cannot age energy twice");relog();output("elapsed_relogged",3);
 apply(timer(0,true));Check(state.recovery.effects.size()==1 && state.recovery.effects[0].remainingMs==1787655,"original energy remains after actual death-normalization commit");output("dead",3);
 apply(timer(1800000,false));Check(state.recovery.effects.empty() && state.items[0].energy==source.energy,"expiry clears effect without rerolling remaining crystal");output("expired",1);
 const auto again=MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,source.id,actor,0,now,2);Check(again.has_value(),"remaining crystal usable after expiry");apply(*again);Check(state.items.empty(),"last real crystal consumed");output("used_again",3);
 const auto cancel=MakeItemEffectCancel(*catalog,op(),state.fence,state.recovery,0,now,state.recovery.generation,2);Check(cancel.has_value(),"native exact effect cancellation admitted");apply(*cancel);Check(state.recovery.effects.empty(),"cancel removes actual energy effect");output("cancelled",3);relog();output("final_relogged",3);
 store.Stop();std::cout<<"SOURCE_ENERGY_CRYSTAL_WORKER=SUCCESS sources=1 packets="<<packets<<" checks="<<checks<<std::endl;
}
